async function(PIXI, app, api) {
  const root = new PIXI.Container();
  app.stage.addChild(root);
  const backdrop = new PIXI.Graphics(), path = new PIXI.Graphics(), trail = new PIXI.Graphics();
  const vector = new PIXI.Graphics(), launch = new PIXI.Graphics();
  root.addChild(backdrop, path, trail, launch, vector);
  const ball = new PIXI.Container();
  ball.addChild(new PIXI.Graphics().circle(0,0,10).fill({color:'#ed7c36'}).stroke({color:'#833b23',width:2}));
  ball.addChild(new PIXI.Graphics().arc(0,0,7,-1.4,1.4).stroke({color:'#ffe3ae',width:2}));
  ball.addChild(new PIXI.Graphics().moveTo(-9,0).lineTo(9,0).stroke({color:'#833b23',width:1.5}));
  root.addChild(ball);
  function label(size,weight='normal') {
    const t=new PIXI.Text({text:'',style:{fontFamily:'Arial',fontSize:size,fontWeight:weight,fill:'#183b49'}});
    root.addChild(t); return t;
  }
  const title=label(21,'bold'), subtitle=label(12), groundText=label(12,'bold');
  const markerText=label(11), ballText=label(12,'bold'), reading=label(13), note=label(12);
  const status=label(13,'bold');
  let width=1,height=1,scale=1,left=0,top=0,xmin=0,ymax=0,rows=[],lastFrame=null;
  let colors={};
  function point(x,y){return {x:left+(x-xmin)*scale,y:top+(ymax-y)*scale};}
  function layout() {
    width=api.width; height=api.height;
    const dark=api.theme==='DARK';
    colors={ink:dark?'#e1edf1':'#183b49',muted:dark?'#aec0c9':'#5c727d',sky:dark?'#18333f':'#e4f3f6',soil:dark?'#352c27':'#f0e5d7',line:dark?'#a78d72':'#957a58',paper:dark?'#102630':'#ffffff'};
    for(const t of [title,subtitle,groundText,markerText,ballText,reading,note,status])t.style.fill=colors.ink;
    rows=api.timeline.frames;
    const ranges=api.getFieldRanges();
    xmin=Math.min(0,ranges['p1.x'].min);
    const xmax=Math.max(xmin+1,ranges['p1.x'].max);
    const ymin=Math.min(0,ranges['p1.y'].min), yymax=Math.max(.1,ranges['p1.y'].max);
    const areaW=Math.max(1,width-120), areaH=Math.max(1,height-260);
    scale=Math.min(areaW/(xmax-xmin),areaH/Math.max(1,yymax-ymin));
    ymax=yymax;
    left=60+(areaW-(xmax-xmin)*scale)/2;
    top=94;
    const ground=point(xmin,0).y;
    backdrop.clear().rect(0,0,width,height).fill({color:colors.paper});
    backdrop.rect(16,78,width-32,Math.max(1,ground-78)).fill({color:colors.sky});
    backdrop.rect(16,ground,width-32,Math.max(1,height-102-ground)).fill({color:colors.soil});
    backdrop.moveTo(16,ground).lineTo(width-16,ground).stroke({color:colors.line,width:3});
    // A minimal school fence is context; it does not replace physical data.
    if(ground>112){
      for(let i=0;i<8;i++){const x=25+i*(width-50)/7;backdrop.moveTo(x,ground-18).lineTo(x,ground-4);}
      backdrop.stroke({color:colors.muted,width:1,alpha:.25});
    }
    title.text='Ném bóng ở sân trường'; title.position.set(20,16);
    subtitle.text='Tọa độ từ solver · x và y cùng tỉ lệ · mũi tên chỉ vận tốc';
    subtitle.style.wordWrap=true;subtitle.style.wordWrapWidth=width-40;subtitle.position.set(20,44);
    groundText.text='Mặt đất · y = 0 m';groundText.position.set(23,ground+7);
    markerText.text='Điểm ném';
    const first=rows[0].values, start=point(first['p1.x'],first['p1.y']);
    launch.clear().circle(start.x,start.y,4).fill({color:'#507e8a'});
    markerText.position.set(Math.max(20,start.x-32),Math.max(80,start.y-24));
    path.clear();
    for(let i=1;i<rows.length;i++) {
      const a=rows[i-1].values,b=rows[i].values,pa=point(a['p1.x'],a['p1.y']),pb=point(b['p1.x'],b['p1.y']);
      if(b['p1.y']>=0||i%2===0)path.moveTo(pa.x,pa.y).lineTo(pb.x,pb.y).stroke({color:b['p1.y']>=0?'#6b9dad':'#b87d52',width:2,alpha:.45});
    }
    reading.style.fontSize=width<500?12:14;
    reading.style.wordWrap=true;reading.style.wordWrapWidth=width-40;reading.position.set(20,height-92);
    status.style.wordWrap=true;status.style.wordWrapWidth=width-40;status.position.set(20,height-54);
    note.text='Nét đứt dưới đất: dữ liệu ngoại suy. Chưa có xử lý va chạm.';
    note.style.wordWrap=true;note.style.wordWrapWidth=width-40;note.style.fontSize=width<500?10:12;note.style.fill=colors.muted;note.position.set(20,height-29);
  }
  function update(frame) {
    lastFrame=frame;
    const f=frame.fields, p=point(f['p1.x'],f['p1.y']);
    ball.position.set(p.x,p.y); ball.alpha=f['p1.y']<0?.6:1;
    trail.clear();
    for(let i=1;i<rows.length && rows[i].t<=frame.t;i++){
      const a=rows[i-1].values,b=rows[i].values,pa=point(a['p1.x'],a['p1.y']),pb=point(b['p1.x'],b['p1.y']);
      if(b['p1.y']>=0||i%2===0)trail.moveTo(pa.x,pa.y).lineTo(pb.x,pb.y).stroke({color:b['p1.y']>=0?'#148b86':'#b87343',width:3});
    }
    const ranges=api.getFieldRanges(), arrowScale=48/Math.max(1,ranges['p1.speed'].max);
    const dx=f['p1.vx']*arrowScale,dy=-f['p1.vy']*arrowScale,ex=p.x+dx,ey=p.y+dy;
    const angle=Math.atan2(dy,dx);
    vector.clear().moveTo(p.x,p.y).lineTo(ex,ey).stroke({color:'#246dba',width:3});
    vector.moveTo(ex-8*Math.cos(angle-.5),ey-8*Math.sin(angle-.5)).lineTo(ex,ey).lineTo(ex-8*Math.cos(angle+.5),ey-8*Math.sin(angle+.5)).stroke({color:'#246dba',width:3});
    ballText.text='v = '+f['p1.speed'].toFixed(2)+' m/s';
    ballText.position.set(Math.max(20,Math.min(width-ballText.width-20,p.x+16)),Math.max(78,Math.min(height-113,p.y-24)));
    reading.text='x '+f['p1.x'].toFixed(2)+' m    y '+f['p1.y'].toFixed(2)+' m\nvₓ '+f['p1.vx'].toFixed(2)+' m/s    vᵧ '+f['p1.vy'].toFixed(2)+' m/s';
    status.text=f['p1.y']<0?'⚠ Solver chưa dừng khi bóng chạm đất.':'Quan sát quỹ đạo và hướng vận tốc của bóng.';
    status.style.fill=f['p1.y']<0?'#b65c2b':colors.ink;
  }
  layout();
  return {update,setData(){layout();if(lastFrame)update(api.getFrame());},resize(){layout();if(lastFrame)update(api.getFrame());},destroy(){root.destroy({children:true});}};
}
